function copy(task: ScheduledTask): ScheduledTask {
  return {
    ...task,
    createdAt: new Date(task.createdAt),
    nextFireAt: new Date(task.nextFireAt),
    lastFiredAt: task.lastFiredAt ? new Date(task.lastFiredAt) : undefined,
