function taskRows(batch: Batch): { tasks: RenderTask[]; errors: string[] } {
  const order: string[] = [];
  const tasks = new Map<string, RenderTask>();
  const errors: string[] = [];
  let anonymous = 0;
  for (const result of batch.results) {
    if (result.error) {
      errors.push(result.error.message || "Task update failed");
      continue;
