export type AgentKind = "pi-session" | "pi-headless" | "external";
export type AgentLifecycle = "starting" | "idle" | "running" | "waiting" | "stopped" | "failed";
export type JobState = "queued" | "leased" | "running" | "succeeded" | "failed" | "cancelled";

