    let request: JsonRpcRequest;
    try { const raw=JSON.parse(line) as unknown; if(!raw||typeof raw!=="object"||Array.isArray(raw)) throw new Error(); request=raw as JsonRpcRequest; if(typeof request.request_id!=="string"||!request.request_id||typeof request.method!=="string") throw new Error(); } catch { return {request_id:"",ok:false,error:{code:"invalid_request",message:"malformed JSON-RPC request",retryable:false}}; }
