  const children = new Map<string, Task[]>();
  const roots: Task[] = [];
  for (const task of open) {
    if (task.parentTaskId && visible.has(task.parentTaskId))
      children.set(task.parentTaskId, [...(children.get(task.parentTaskId) ?? []), task]);
