    output.push({ task, depth });
    for (const child of (children.get(task.id) ?? []).sort((a, b) => rank(a) - rank(b))) visit(child, depth + 1);
  };
  for (const task of roots.sort((a, b) => rank(a) - rank(b))) visit(task, 0);
