    while (true) { try { await mkdir(this.lockPath, { mode: 0o700 }); break; } catch (e) { if ((e as NodeJS.ErrnoException).code !== "EEXIST" || Date.now() >= deadline) throw new ControlPlaneError("conflict", "control-plane store is busy"); await new Promise(r => setTimeout(r, 5)); } }
    try {
      let state = empty();
      try { state = migrate(JSON.parse(await readFile(this.path, "utf8"))); } catch (e) { if ((e as NodeJS.ErrnoException).code !== "ENOENT") throw e; }
      const result = await fn(state);
      const tmp = `${this.path}.tmp-${process.pid}-${crypto.randomUUID()}`;
      await writeFile(tmp, `${JSON.stringify(state)}\n`, { encoding: "utf8", mode: 0o600, flag: "wx" });
      await rename(tmp, this.path); await rm(tmp, { force: true });
      return result;
    } finally { await rm(this.lockPath, { recursive: true, force: true }); }
