  async heartbeatAgent(id: ID, actor: string, at = iso()): Promise<AgentBinding> { return this.locked(s => { const a=required(s.agents.find(x=>x.id===id), `agent ${id} not found`); const n={...a,status:a.status==="starting"?"idle":a.status,lastHeartbeatAt:at,revision:a.revision+1,updatedAt:iso()} as AgentBinding; s.agents[s.agents.indexOf(a)]=n; this.event(s,"agent.heartbeat",id,actor); return clone(n); }); }
  async stopAgent(id: ID, actor: string): Promise<AgentBinding> { return this.locked(s => { const a=required(s.agents.find(x=>x.id===id), `agent ${id} not found`); const n={...a,status:"stopped" as const,revision:a.revision+1,updatedAt:iso()}; s.agents[s.agents.indexOf(a)]=n; this.event(s,"agent.stopped",id,actor); return clone(n); }); }
  async createJob(request: CreateJobRequest, actor: string): Promise<Job> { return this.locked(s => { if(!request.request.prompt.trim()||!request.idempotencyKey.trim()) fail("invalid_request","prompt and idempotencyKey are required"); const old=s.jobs.find(j=>j.idempotencyKey===request.idempotencyKey); if(old)return clone(old); const t=iso(); const j:Job={id:`job:${crypto.randomUUID()}` as ID,request:clone(request.request),policyProfile:request.policyProfile,state:"queued",attempt:0,idempotencyKey:request.idempotencyKey,createdAt:t,updatedAt:t}; s.jobs.push(j); this.event(s,"job.created",j.id,actor); return clone(j); }); }
  async getJob(id: ID): Promise<Job> { return this.locked(s => { const j=required(s.jobs.find(x=>x.id===id), `job ${id} not found`); return clone(j); }); }
  async cancelJob(id: ID, actor: string): Promise<Job> { return this.locked(s => this.transition(s,id,"cancelled",actor,"job.cancelled")); }
  async retryJob(id: ID, actor: string): Promise<Job> { return this.locked(s => { const j=required(s.jobs.find(x=>x.id===id), `job ${id} not found`); if(j.state!=="failed"&&j.state!=="cancelled")fail("conflict",`job ${id} is not retryable`); const n={...j,state:"queued" as const,attempt:j.attempt+1,updatedAt:iso()}; s.jobs[s.jobs.indexOf(j)]=n; this.event(s,"job.retried",id,actor); return clone(n); }); }
  private transition(s:State,id:ID,state:"cancelled",actor:string,type:ControlPlaneEvent["type"]):Job { const j=required(s.jobs.find(x=>x.id===id), `job ${id} not found`); if(["succeeded","failed","cancelled"].includes(j.state))fail("already_terminal",`job ${id} is terminal`); const n={...j,state,updatedAt:iso()}; s.jobs[s.jobs.indexOf(j)]=n; this.event(s,type,id,actor); return clone(n); }
